'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session=null,store={companies:[],contacts:[],contact_emails:[],notes:[],followups:[],activities:[],images:[]},searchTerm='',directoryView='contacts',showArchived=false,reminderScope='Tous';
const dialog=document.querySelector('#detail');
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const isAdmin=()=>session?.organization.role==='admin';
const memberName=id=>session?.members.find(m=>m.id===id)?.name||'Non attribué';
const companyBy=id=>store.companies.find(c=>c.id===id);
const contactBy=id=>store.contacts.find(c=>c.id===id);
const addressFor=id=>store.contact_emails.filter(e=>e.contact_id===id).map(e=>e.email);
const localDate=v=>new Intl.DateTimeFormat('fr-TN',{timeZone:'Africa/Tunis',dateStyle:'medium',timeStyle:'short',hourCycle:'h23'}).format(new Date(v));
const dayKey=v=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Tunis',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
const today=()=>dayKey(new Date());
const pending=()=>store.followups.filter(f=>f.status==='pending');
function errorText(message){return `<p class="connection-error" role="alert">${esc(message)}</p>`;}
async function api(path,options={}){const requestGeneration=workspaceGeneration;const response=await fetch('/api/v1'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(session?{'X-CSRF-Token':session.csrfToken}:{}),...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});if(requestGeneration!==workspaceGeneration)throw Error('Espace de travail modifié.');if(response.status===204)return null;const data=await response.json();if(!response.ok){if(response.status===401&&location.pathname.startsWith('/app')){++workspaceGeneration;++loadSequence;session=null;store=emptyStore();go('/connexion');}throw Error(data.message||'La requête a échoué.');}return data;}
let workspaceGeneration=0,loadSequence=0,viewSequence=0,recordSequence=0,directorySequence=0,agendaPage=1;
let dashboardData=null,facets=[],directoryTotal=0;
const emptyStore=()=>({companies:[],contacts:[],contact_emails:[],notes:[],followups:[],activities:[],images:[]});
function mergeData(data){for(const key of Object.keys(emptyStore())){if(!data?.[key])continue;const rows=new Map((store[key]||[]).map(r=>[r.id,r]));for(const row of data[key])rows.set(row.id,row);store[key]=[...rows.values()].slice(key==='contact_emails'?-3000:-300);}}
function mergePage(type,data){mergeData(data.related);mergeData({[type]:data.items});}
async function load(){const seq=++loadSequence,generation=workspaceGeneration;const [account,summary,filters,activity]=await Promise.all([api('/me'),api('/dashboard'),api('/directory-facets'),api('/activities?limit=8')]);if(seq!==loadSequence||generation!==workspaceGeneration)return false;session=account;store=emptyStore();store.activities=activity.items;dashboardData=summary;facets=filters.sectors;for(const page of Object.values(summary.periods))mergePage('followups',page);return true;}

async function sync(){if(await load())await render();}
function go(path){++viewSequence;++recordSequence;++directorySequence;dialog.close();history.pushState({},'',path);searchTerm='';render();window.scrollTo(0,0);}
function safeAction(fn){return async()=>{try{await fn();}catch(e){toast(e.message);}};}
function bindForm(id,handler){const f=document.getElementById(id);if(!f.closest('.auth-card'))enhanceFormFields(f);f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button[type="submit"]');if(b.disabled)return;const data=Object.fromEntries(new FormData(f));b.disabled=true;let errors=f.querySelector('[role="alert"]');if(errors)errors.remove();try{await handler(data,f);}catch(err){f.insertAdjacentHTML('beforeend',errorText(err.message));}finally{b.disabled=false;}};}
function modal(title,body,drawer=false){++recordSequence;dialog.classList.toggle('contact-drawer',drawer);document.querySelector('#detail-content').innerHTML=`<h2 id="detail-title">${esc(title)}</h2>${body}`;dialog.showModal();enhanceFormFields(dialog);}
function links(){return [['grid','Tableau de bord','/app'],['people','Contacts','/app/contacts'],['building','Entreprises','/app/contacts?vue=entreprises'],['clock','Relances','/app/relances']];}
function shell(content){
  const path=location.pathname,user=session.user;
  app.innerHTML=`<div class="workspace workspace-chrome"><aside class="sidebar"><div class="sidebar-header">${brand}</div><div id="workspace-navigation"><nav aria-label="Navigation principale">${links().map(([i,n,p])=>{const selected=path===p.split('?')[0]&&(p.includes('?')?location.search.includes('vue=entreprises'):p!=='/app/contacts'||!location.search.includes('vue=entreprises'));return `<a href="${p}" class="nav-item ${selected?'selected':''}" ${selected?'aria-current="page"':''} title="${esc(n)}">${icon(i)} <span class="nav-label">${n}</span></a>`;}).join('')}</nav><div class="sidebar-bottom"><a class="nav-item ${path==='/app/parametres'?'selected':''}" href="/app/parametres" ${path==='/app/parametres'?'aria-current="page"':''} title="Paramètres">${icon('settings')} <span class="nav-label">Paramètres</span></a><div class="sidebar-footer"><strong>Ciblix</strong><span class="nav-label">Votre espace de travail</span></div></div></div></aside><div class="workspace-main"><header class="dashboard-top"><div class="header-workspace"><button class="icon-button workspace-menu" id="workspace-menu" aria-label="Réduire le menu" aria-expanded="true" aria-controls="workspace-navigation"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M5 7h14M5 12h14M5 17h14"/></svg></button><button class="workspace-switch" id="switch-org"><span><strong>${esc(session.organization.name)}</strong></span><span aria-hidden="true">⌄</span></button></div><div class="global-search"><label class="search-box">${icon('search')}<input id="global-search" type="search" placeholder="Rechercher partout…" aria-label="Recherche globale"></label><div id="global-results" class="global-results" hidden></div></div><div class="top-actions"><time class="header-date" datetime="${today()}">${esc(new Intl.DateTimeFormat('fr-TN',{timeZone:'Africa/Tunis',dateStyle:'short'}).format(new Date()))}</time><button class="icon-button" id="refresh-workspace" aria-label="Actualiser les données" title="Actualiser les données">↻</button><div class="profile header-profile"><span class="avatar dark">${esc(initials(user.name))}</span><div><strong>${esc(user.name)}</strong><small>${isAdmin()?'Administrateur':'Collaborateur'}</small></div><button id="signout" aria-label="Se déconnecter" title="Se déconnecter">↗</button></div></div></header><main class="dashboard-content">${content}</main></div></div>`;
  const menu=document.querySelector('#workspace-menu'),chrome=document.querySelector('.workspace-chrome');
  const setMenu=open=>{menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Réduire le menu':'Ouvrir le menu');chrome.classList.toggle('navigation-collapsed',!open);chrome.classList.toggle('navigation-open',open);};
  const sidebar=chrome.querySelector('.sidebar');
  setMenu(false);
  menu.onclick=()=>setMenu(menu.getAttribute('aria-expanded')!=='true');
  sidebar.onpointerenter=e=>{if(e.pointerType==='mouse'&&window.matchMedia('(min-width: 1025px)').matches)setMenu(true);};
  sidebar.onpointerleave=e=>{if(e.pointerType==='mouse'&&!sidebar.contains(document.activeElement))setMenu(false);};
  sidebar.onclick=()=>setMenu(true);
  sidebar.onfocusin=()=>setMenu(true);
  sidebar.onfocusout=e=>{if(!sidebar.contains(e.relatedTarget)&&!sidebar.matches(':hover'))setMenu(false);};
  chrome.onpointerdown=e=>{if(!sidebar.contains(e.target)&&!menu.contains(e.target))setMenu(false);};
  document.querySelector('#workspace-navigation').onkeydown=e=>{if(e.key==='Escape'){setMenu(false);menu.focus();}};
  document.querySelector('#signout').onclick=safeAction(async()=>{await api('/auth/logout',{method:'POST'});++workspaceGeneration;++loadSequence;session=null;store=emptyStore();go('/connexion');});
  document.querySelector('#refresh-workspace').onclick=refreshWorkspace;
  document.querySelector('#switch-org').onclick=switchOrg;

  const createButton=document.querySelector('#global-add');
  if(createButton)createButton.onclick=()=>{modal('Créer',`<div class="board-dialog-actions"><button class="button" id="new-contact">${icon('people')} Contact</button><button class="button board-secondary" id="new-company">${icon('building')} Entreprise</button><button class="button board-secondary" id="new-followup">${icon('clock')} Relance</button></div>`);document.querySelector('#new-company').onclick=()=>entityForm('companies');document.querySelector('#new-contact').onclick=()=>entityForm('contacts');document.querySelector('#new-followup').onclick=()=>followupForm();};
  // A secondary creation menu remains available without competing with the page action.

  bindGlobalSearch();
}
function greeting(title,_description,action){return `<div class="greeting page-greeting"><h1>${esc(title)}</h1>${action?`<button class="button" id="page-add">＋ ${esc(action)}</button>`:''}</div>`;}
function reminderRow(r){
  const person=contactBy(r.contact_id),company=companyBy(r.company_id),late=r.status==='pending'&&dayKey(r.due_at)<today();
  return `<article class="board-reminder ${late?'reminder-overdue':''}"><button class="board-person" ${person?`data-open-contact="${person.id}"`:company?`data-open-company="${company.id}"`:'disabled'}><span class="avatar">${esc(initials(person?.name||company?.name||'R'))}</span><span><strong>${esc(person?.name||company?.name||'Sans contact')}</strong>${person&&company?`<small>${esc(company.name)}</small>`:''}</span></button><time datetime="${esc(r.due_at)}">${esc(localDate(r.due_at))}</time><div class="board-reminder-context"><p>${esc(r.subject)}</p><span>${esc(memberName(r.owner_user_id))}</span></div><div class="reminder-actions">${r.status==='pending'?`<button class="icon-button" data-complete-followup="${r.id}" aria-label="Terminer : ${esc(r.subject)}" title="Terminer">${icon('check')}</button><button class="icon-button" data-edit-followup="${r.id}" aria-label="Reporter : ${esc(r.subject)}" title="Reporter">${icon('clock')}</button>`:''}<button class="icon-button" data-draft="${r.id}" aria-label="Brouillon : ${esc(r.subject)}" title="Brouillon">${icon('mail')}</button><button class="icon-button" data-followup-actions="${r.id}" aria-label="Actions : ${esc(r.subject)}">···</button></div></article>`;
}
function activityRows(){return store.activities.slice(0,8).map(a=>`<div class="board-activity-row"><span class="timeline-dot"></span><span class="avatar">${esc(initials(a.actor_name))}</span><div><p><strong>${esc(a.actor_name)}</strong> · ${esc(a.summary)}</p><small>${esc(localDate(a.created_at))}</small></div></div>`).join('')||'<p class="empty">Aucune activité.</p>';}
let evolutionMonths=12;
const chartColors=['#013BE5','#07C00D','#4C6EF5','#05A00A','#7AA0FF'];
function contactEvolution(){const values=dashboardData.evolution.slice(-evolutionMonths),max=Math.max(5,...values.map(v=>v.count));return `<div class="contact-evolution" role="img" aria-label="Évolution des contacts"><div class="evolution-axis">${Array.from({length:6},(_,i)=>`<span>${Math.round(max*(5-i)/5)}</span>`).join('')}</div><div class="evolution-bars">${values.map(v=>`<div class="evolution-bar"><svg viewBox="0 0 24 160" preserveAspectRatio="none" aria-hidden="true"><rect x="2" y="${160-v.count/max*160}" width="20" height="${v.count/max*160}" rx="3" fill="#013BE5"/></svg><span>${new Date(v.month+'-01T12:00:00Z').toLocaleDateString('fr-TN',{month:'short',timeZone:'UTC'})}</span></div>`).join('')}</div></div>`;}

function contactOrigins(){const counts=new Map(dashboardData.origins.map(v=>[v.name,v.count]));const total=[...counts.values()].reduce((a,b)=>a+b,0);const groups=[...counts].sort((a,b)=>b[1]-a[1]);let offset=0;return `<div class="origins-chart"><div class="donut-figure"><svg viewBox="0 0 150 150" class="origin-donut" role="img" aria-label="Origine des ${total} contacts"><circle cx="75" cy="75" r="56" fill="none" stroke="#E7EEFC" stroke-width="18"/>${groups.map(([name,value],i)=>{const length=value/(total||1)*351.858;const part=`<circle cx="75" cy="75" r="56" fill="none" stroke="${chartColors[i%chartColors.length]}" stroke-width="18" stroke-dasharray="${length} ${351.858-length}" stroke-dashoffset="${-offset}" transform="rotate(-90 75 75)"><title>${esc(name)} : ${value}</title></circle>`;offset+=length;return part;}).join('')}</svg><div class="donut-center" aria-hidden="true"><strong>${total}</strong><span>contacts</span></div></div><div class="origin-legend">${groups.map(([n,v],i)=>`<div><svg viewBox="0 0 10 10" aria-hidden="true"><circle cx="5" cy="5" r="5" fill="${chartColors[i%chartColors.length]}"/></svg><span>${esc(n)}</span><strong>${Math.round(v/(total||1)*100)}%</strong></div>`).join('')||'<p>Les origines apparaîtront après vos premiers ajouts.</p>'}</div></div>`;}
function sectorChart(){const counts=new Map(dashboardData.sectors.map(v=>[v.name,v.count]));const total=dashboardData.counts.contacts;return `<div class="sector-chart">${[...counts].sort((a,b)=>b[1]-a[1]).slice(0,6).map(([n,v],i)=>{const pct=Math.round(v/(total||1)*100);return `<div><span>${esc(n)}</span><svg viewBox="0 0 130 13" aria-hidden="true"><rect width="130" height="13" rx="6" fill="#E7EEFC"/><rect width="${130*pct/100}" height="13" rx="6" fill="${['#013BE5','#07C00D','#4C6EF5','#05A00A','#7AA0FF','#475569'][i]}"/></svg><strong>${pct}%</strong></div>`;}).join('')||'<p class="empty">Les secteurs des entreprises associées à vos contacts apparaîtront ici.</p>'}</div>`;}
function dashboardLive(){
  document.title='Tableau de bord — Ciblix';const counts=dashboardData.counts,periods=dashboardData.periods;
  const metrics=[['people','Contacts',counts.contacts,'/app/contacts'],['building','Entreprises',counts.companies,'/app/contacts?vue=entreprises'],['clock','Aujourd’hui',periods.today.total,'/app/relances?periode=today'],['bell','En retard',periods.late.total,'/app/relances?periode=late']];
  const periodList=(key,title)=>`<section class="panel board-panel followup-${key}"><div class="board-panel-heading"><h2>${title} <span class="number-tag">${periods[key].total}</span></h2><a href="/app/relances?periode=${key}" aria-label="Voir les relances : ${title}">Voir tout ${icon('arrow')}</a></div>${periods[key].items.map(reminderRow).join('')||`<div class="followup-empty"><span>${icon(key==='late'?'check':'clock')}</span><p>${key==='late'?'Vous êtes à jour':'Aucune relance '+(key==='today'?'aujourd’hui':'à venir')}</p></div>`}</section>`;
  shell(`<div class="dashboard-overview"><div class="board-welcome"><h1>Tableau de bord</h1><div class="dashboard-title-actions"><time>${esc(new Intl.DateTimeFormat('fr-TN',{timeZone:'Africa/Tunis',dateStyle:'long'}).format(new Date()))}</time><button class="button" id="global-add">＋ Créer</button></div></div><section class="board-metrics" aria-label="Indicateurs">${metrics.map(([i,label,value,url])=>`<a class="board-metric" href="${url}"><span class="metric-icon">${icon(i)}</span><div><span>${label}</span><strong>${value}</strong></div></a>`).join('')}</section><div class="dashboard-followups" id="dashboard-tasks">${periodList('today','Aujourd’hui')}${periodList('late','En retard')}${periodList('upcoming','À venir')}</div><details class="dashboard-statistics" id="dashboard-stats" open><summary>Statistiques des contacts</summary><section class="dashboard-analytics" aria-label="Statistiques des contacts"><article class="panel"><div class="analytics-heading"><h2>Évolution</h2><label><span class="sr-only">Période du graphique</span><select id="evolution-period"><option value="12" ${evolutionMonths===12?'selected':''}>12 mois</option><option value="6" ${evolutionMonths===6?'selected':''}>6 mois</option></select></label></div>${contactEvolution()}</article><article class="panel"><div class="analytics-heading"><h2>Origines</h2></div>${contactOrigins()}</article><article class="panel"><div class="analytics-heading"><h2>Secteurs</h2></div>${sectorChart()}</article></section></details><section class="panel recent-activity"><div class="panel-heading"><h2>Activité récente</h2></div>${activityRows()}</section></div>`);
  bindRecords();document.querySelector('#evolution-period').onchange=e=>{evolutionMonths=Number(e.target.value);const open=document.querySelector('#dashboard-stats').open;dashboardLive();document.querySelector('#dashboard-stats').open=open;};
}

const directoryState={owner:'',sector:'',status:'',page:1,pageSize:10,sort:'name',direction:1};
function followupsFor(c,type){return pending().filter(r=>type==='companies'?r.company_id===c.id:r.contact_id===c.id).sort((a,b)=>new Date(a.due_at)-new Date(b.due_at));}
function tracking(c,type){if(c.archived_at)return {key:'archived',label:'Archivé'};if(c.tracking_key){const labels={archived:'Archivé',late:'En retard',planned:'Relance prévue',done:'Suivi terminé',none:'À organiser'};return {key:c.tracking_key,label:labels[c.tracking_key]};}const next=followupsFor(c,type);if(next.some(r=>dayKey(r.due_at)<today()))return {key:'late',label:'En retard'};if(next.length)return {key:'planned',label:'Relance prévue'};const related=store.followups.filter(r=>type==='companies'?r.company_id===c.id:r.contact_id===c.id);if(related.length&&related.every(r=>r.status==='completed'||r.status==='cancelled'))return {key:'done',label:'Suivi terminé'};return {key:'none',label:'À organiser'};}
function directoryPeople(c,type){return type==='companies'?store.contacts.filter(p=>p.company_id===c.id&&!p.archived_at):[];}
function directorySector(c,type){return type==='companies'?c.sector:companyBy(c.company_id)?.sector||'';}
function directory(){document.title='Entreprises & contacts — Ciblix';directoryView=new URLSearchParams(location.search).get('vue')==='entreprises'?'companies':'contacts';const company=directoryView==='companies';const sectors=facets;shell(`<div class="directory-heading"><h1>${company?'Entreprises':'Contacts'}</h1><button class="button" id="page-add">＋ ${company?'Ajouter une entreprise':'Ajouter un contact'}</button></div><section class="directory-surface"><div class="directory-switcher"><div class="entity-tabs" role="group" aria-label="Vue du répertoire"><button data-directory="companies" class="${company?'active':''}" aria-pressed="${company}">${icon('building')} Entreprises <span>${dashboardData.counts.companies}</span></button><button data-directory="contacts" class="${!company?'active':''}" aria-pressed="${!company}">${icon('people')} Contacts <span>${dashboardData.counts.contacts}</span></button></div><div class="directory-tools"><button class="text-link" id="export">Exporter les contacts ${icon('arrow')}</button>${!company?`<label class="card-photo-button">${icon('phone')} Carte de visite<input id="photo-card" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></label>`:''}</div></div><div class="directory-filter-bar"><label class="search-box">${icon('search')}<input id="directory-search" type="search" value="${esc(searchTerm)}" placeholder="Nom, entreprise, e-mail, téléphone…" aria-label="Rechercher dans le répertoire"></label><button class="directory-filter-toggle" id="toggle-directory-filters" aria-expanded="false">Filtres</button><label class="filter-select"><span>Responsable</span><select id="filter-owner"><option value="">Tous les responsables</option>${session.members.map(m=>`<option value="${m.id}" ${directoryState.owner===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}<option value="unassigned" ${directoryState.owner==='unassigned'?'selected':''}>Non attribué</option></select></label><label class="filter-select"><span>Secteur</span><input id="filter-sector" list="sector-options" value="${esc(directoryState.sector)}" placeholder="Tous les secteurs"><datalist id="sector-options">${sectors.map(s=>`<option value="${esc(s)}"></option>`).join('')}</datalist></label><label class="filter-select"><span>Suivi</span><select id="filter-status"><option value="">Tous les statuts</option>${[['late','En retard'],['planned','Relance prévue'],['none','À organiser'],['done','Suivi terminé'],['archived','Archivé']].map(([v,n])=>`<option value="${v}" ${directoryState.status===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="directory-list-meta"><p id="result-count" aria-live="polite"></p><div><label><input id="show-archived" type="checkbox" ${showArchived?'checked':''}> Inclure les archives</label><button id="reset-directory" class="text-link">Réinitialiser</button></div></div><div class="directory-mobile-sort"><label>Trier par<select id="mobile-sort"><option value="name">Nom</option><option value="relation">Entreprise / interlocuteur</option><option value="owner">Responsable</option><option value="next">Prochaine relance</option><option value="status">Statut du suivi</option></select></label><label>Ordre<select id="mobile-sort-direction"><option value="1">Croissant</option><option value="-1">Décroissant</option></select></label></div><div id="directory-results"></div><div id="directory-pagination" class="directory-pagination"></div></section>`);document.querySelector('#page-add').onclick=()=>entityForm(directoryView);document.querySelectorAll('[data-directory]').forEach(b=>b.onclick=()=>{directoryState.page=1;directoryState.sector='';go('/app/contacts'+(b.dataset.directory==='companies'?'?vue=entreprises':''));});document.querySelector('#directory-search').oninput=e=>{searchTerm=e.target.value;directoryState.page=1;directoryResults();};for(const key of ['owner','sector','status'])document.querySelector('#filter-'+key).onchange=e=>{directoryState[key]=e.target.value;directoryState.page=1;directoryResults();};document.querySelector('#show-archived').onchange=e=>{showArchived=e.target.checked;directoryState.page=1;directoryResults();};document.querySelector('#reset-directory').onclick=resetDirectory;document.querySelector('#toggle-directory-filters').onclick=e=>{const expanded=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',String(expanded));document.querySelector('.directory-filter-bar').classList.toggle('filters-expanded',expanded);};document.querySelector('#export').onclick=safeAction(exportContacts);document.querySelector('#mobile-sort').onchange=e=>{directoryState.sort=e.target.value;directoryState.page=1;directoryResults();};document.querySelector('#mobile-sort-direction').onchange=e=>{directoryState.direction=Number(e.target.value);directoryState.page=1;directoryResults();};document.querySelector('#photo-card')?.addEventListener('change',e=>{if(e.target.files[0])entityForm('contacts',null,e.target.files[0]);});return directoryResults();}
function resetDirectory(){Object.assign(directoryState,{owner:'',sector:'',status:'',page:1,sort:'name',direction:1});showArchived=false;searchTerm='';directory();}
function directoryQuery(){return new URLSearchParams({q:searchTerm,owner:directoryState.owner,sector:directoryState.sector,status:directoryState.status,archived:String(showArchived),sort:directoryState.sort,direction:directoryState.direction===1?'asc':'desc',limit:directoryState.pageSize,offset:(directoryState.page-1)*directoryState.pageSize});}
async function directoryResults(){const seq=++directorySequence,generation=workspaceGeneration,type=directoryView,company=type==='companies',state={...directoryState};const host=document.querySelector('#directory-results');if(!host)return;host.setAttribute('aria-busy','true');try{const data=await api('/'+type+'?'+directoryQuery());if(seq!==directorySequence||generation!==workspaceGeneration||!host.isConnected)return;mergePage(type,data);const total=data.total,pages=Math.max(1,Math.ceil(total/state.pageSize));directoryTotal=total;if(state.page>pages){directoryState.page=pages;return directoryResults();}const start=(state.page-1)*state.pageSize,items=data.items;document.querySelector('#mobile-sort').value=state.sort;document.querySelector('#mobile-sort-direction').value=String(state.direction);document.querySelector('#result-count').textContent=`${total} ${company?'entreprise'+(total>1?'s':''):'contact'+(total>1?'s':'')}${searchTerm||state.owner||state.sector||state.status?' · filtrés':''}`;

const columns=[['name',company?'Entreprise':'Contact'],['relation',company?'Interlocuteur principal':'Entreprise'],['owner','Responsable'],['next','Prochaine relance'],['status','Suivi']];document.querySelector('#directory-results').innerHTML=total?`<table class="directory-table"><caption class="sr-only">${company?'Entreprises':'Contacts'} de votre organisation. Chaque ligne ouvre la fiche.</caption><thead><tr>${columns.map(([key,title])=>`<th scope="col" aria-sort="${state.sort===key?(state.direction===1?'ascending':'descending'):'none'}"><button data-sort="${key}">${title}<span aria-hidden="true">${state.sort===key?(state.direction===1?'↑':'↓'):'↕'}</span></button></th>`).join('')}<th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>${items.map(c=>{const people=c.primary_contact?[c.primary_contact]:[],next=c.next_followup,status=tracking(c,type);return `<tr data-directory-row="${c.id}" tabindex="0" aria-label="Ouvrir la fiche de ${esc(c.name)}" class="${c.archived_at?'archived-row':''}"><td data-label="${company?'Entreprise':'Contact'}"><div class="table-identity"><span class="${company?'company-avatar':'avatar'}">${esc(initials(c.name))}</span><span><a href="${company?'/app/entreprises/'+c.id:'#'}" ${!company?`data-open-directory-contact="${c.id}"`:''}>${esc(c.name)}</a><small>${esc(company?(c.sector||'Secteur non renseigné')+(c.city?' · '+c.city:''):addressFor(c.id)[0]||c.phone||c.job_title||'Coordonnées à compléter')}</small></span></div></td><td data-label="${company?'Interlocuteur':'Entreprise'}"><strong class="table-secondary">${esc(company?people[0]?.name||'Aucun contact':companyBy(c.company_id)?.name||'Sans entreprise')}</strong><small>${company?(c.people_count>1?'+ '+(c.people_count-1)+' autre(s) contact(s)':esc(people[0]?.job_title||'')):esc(c.job_title||'')}</small></td><td data-label="Responsable"><span class="table-owner">${esc(memberName(c.owner_user_id))}</span></td><td data-label="Prochaine relance">${next?`<strong class="table-secondary">${esc(localDate(next.due_at))}</strong><small>${esc(next.subject)}</small>`:'<span class="table-missing">Aucune prévue</span>'}</td><td data-label="Suivi"><span class="tracking-badge tracking-${status.key}">${status.label}</span></td><td class="table-row-actions"><button class="icon-button" data-directory-actions="${c.id}" aria-label="Actions pour ${esc(c.name)}">···</button></td></tr>`;}).join('')}</tbody></table>`:`<div class="directory-empty">${icon(company?'building':'people')}<h2>${dashboardData.counts[type]?'Aucun résultat.':company?'Aucune entreprise.':'Aucun contact.'}</h2><p>${dashboardData.counts[type]?'Modifiez la recherche ou les filtres.':''}</p><button class="button small" id="directory-empty-action">${dashboardData.counts[type]?'Réinitialiser les filtres':company?'Ajouter une entreprise':'Ajouter un contact'}</button></div>`;
document.querySelector('#directory-empty-action')?.addEventListener('click',()=>dashboardData.counts[type]?resetDirectory():entityForm(type));document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{directoryState.direction=state.sort===b.dataset.sort?-state.direction:1;directoryState.sort=b.dataset.sort;directoryState.page=1;directoryResults();});const open=id=>company?go('/app/entreprises/'+id):contactDrawer(id);document.querySelectorAll('[data-directory-row]').forEach(row=>{row.onclick=e=>{if(!e.target.closest('button,a,input,select'))open(row.dataset.directoryRow);};row.onkeydown=e=>{if(e.target===row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();open(row.dataset.directoryRow);}};});document.querySelectorAll('[data-open-directory-contact]').forEach(a=>a.onclick=e=>{e.preventDefault();contactDrawer(a.dataset.openDirectoryContact);});document.querySelectorAll('[data-directory-actions]').forEach(b=>b.onclick=()=>{const c=store[type].find(c=>c.id===b.dataset.directoryActions);modal(c.name,`${recordActions(c,type)}`);bindEntityActions(c,type);});document.querySelector('#directory-pagination').innerHTML=`<span>${total?start+1:0}–${Math.min(start+state.pageSize,total)} sur ${total}</span><label>Lignes par page <select id="page-size">${[10,25,50].map(n=>`<option ${n===state.pageSize?'selected':''}>${n}</option>`).join('')}</select></label><nav aria-label="Pagination du répertoire"><button id="previous-page" ${state.page===1?'disabled':''} aria-label="Page précédente">←</button><span>Page ${state.page} sur ${pages}</span><button id="next-page" ${state.page===pages?'disabled':''} aria-label="Page suivante">→</button></nav>`;document.querySelector('#page-size').onchange=e=>{directoryState.pageSize=Number(e.target.value);directoryState.page=1;directoryResults();};document.querySelector('#previous-page').onclick=()=>{directoryState.page--;directoryResults();};document.querySelector('#next-page').onclick=()=>{directoryState.page++;directoryResults();};}catch(e){if(seq===directorySequence&&host.isConnected)host.innerHTML=errorText(e.message)+'<button class="text-link" id="retry-directory">Réessayer</button>';host.querySelector('#retry-directory')?.addEventListener('click',directoryResults);}finally{if(seq===directorySequence)host.removeAttribute('aria-busy');}}

function ownerOptions(selected){return session.members.filter(m=>m.active).map(m=>`<option value="${m.id}" ${selected===m.id?'selected':''}>${esc(m.name)}</option>`).join('');}
function entityForm(type,id=null,file=null,companyId=null){const company=type==='companies',c=id?store[type].find(c=>c.id===id):{};modal(id?'Modifier la fiche':company?'Ajouter une entreprise':'Ajouter un contact',`<form id="entity-form" class="prototype-form">${file?'<div class="business-card-preview"><p>La photo sera jointe après création du contact. Renseignez les champs manuellement.</p></div>':''}<label>Nom${company?' de l’entreprise':' et prénom'}<input name="name" required maxlength="150" value="${esc(c.name)}"></label>${company?`<label>Secteur<input name="sector" maxlength="150" value="${esc(c.sector)}"></label><label>Ville<input name="city" maxlength="150" value="${esc(c.city)}"></label><label>À propos<textarea name="description" maxlength="5000">${esc(c.description)}</textarea></label>`:`<label>Entreprise<select name="company_id"><option value="">Sans entreprise</option>${store.companies.filter(x=>!x.archived_at).map(x=>`<option value="${x.id}" ${c.company_id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Fonction<input name="job_title" maxlength="150" value="${esc(c.job_title)}"></label><label>E-mails<textarea name="email_list" rows="2" placeholder="contact@entreprise.tn">${esc(id?addressFor(id).join('\n'):'')}</textarea></label><label>Origine<select name="source">${['Non renseignée','Recommandation','Salon / événement','Site web','Prospection','Autre'].map(s=>`<option ${c.source===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Téléphone<input name="phone" type="tel" maxlength="50" value="${esc(c.phone)}"></label>`}<label>Responsable<select name="owner_user_id">${ownerOptions(c.owner_user_id||session.user.id)}</select></label><button class="button" type="submit">Enregistrer ${icon('check')}</button></form>`);groupOptionalFields(document.querySelector('#entity-form'),company?['sector','city','description']:['job_title','source']);bindLookup(document.querySelector('#entity-form select[name=company_id]'),'companies',c.company_id||companyId);bindForm('entity-form',async d=>{if(!company){d.company_id=d.company_id||null;d.emails=d.email_list.split(/[\n;,]+/).map(v=>v.trim()).filter(Boolean);delete d.email_list;}const saved=await api('/'+type+(id?'/'+id:''),{method:id?'PATCH':'POST',body:d});let imageError;if(file){try{await uploadCard(saved.id,file);}catch(e){imageError=e.message;}}dialog.close();await load();await render();if(company)go('/app/entreprises/'+saved.id);else await contactDrawer(saved.id);toast(imageError?'Fiche enregistrée, photo non enregistrée : '+imageError:'Enregistré.');});}
async function uploadCard(id,file){if(file.size>8388608||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choisissez une image PNG, JPEG ou WebP de moins de 8 Mo.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('Lecture de la photo impossible.'));r.readAsDataURL(file);});await api('/contacts/'+id+'/card',{method:'POST',body:{mime_type:file.type,data}});}
function recordActions(c,type){return `<details class="record-action-menu"><summary>Actions</summary><div class="record-action-bar"><button class="text-link" id="record-edit">Modifier</button><button class="text-link" id="record-archive">${c.archived_at?'Restaurer':'Archiver'}</button>${isAdmin()?'<button class="text-link" id="record-delete">Supprimer</button>':''}</div></details>`;}
function bindEntityActions(c,type){document.querySelector('#record-edit').onclick=()=>entityForm(type,c.id);document.querySelector('#record-archive').onclick=safeAction(async()=>{await api('/'+type+'/'+c.id,{method:'PATCH',body:{archived:!c.archived_at}});dialog.close();await sync();toast(c.archived_at?'Fiche restaurée.':'Fiche archivée.');});document.querySelector('#record-delete')?.addEventListener('click',()=>{modal('Confirmer la suppression',`<p>Supprimer définitivement « ${esc(c.name)} » ? ${type==='companies'?'Les contacts associés seront conservés sans entreprise.':''}</p><div class="board-dialog-actions"><button class="button" id="confirm-delete">Confirmer la suppression</button><button class="text-link" id="cancel-delete">Annuler</button></div>`);document.querySelector('#cancel-delete').onclick=()=>dialog.close();document.querySelector('#confirm-delete').onclick=safeAction(async()=>{await api('/'+type+'/'+c.id,{method:'DELETE'});dialog.close();await load();go('/app/contacts'+(type==='companies'?'?vue=entreprises':''));toast('Fiche supprimée.');});});}
function noteItems(notes){return notes.map(n=>`<article class="note-entry"><small>${esc(memberName(n.author_user_id))} · ${esc(localDate(n.created_at))}</small><p class="history-note">${esc(n.body)}</p><button class="text-link" data-note-edit="${n.id}">Modifier</button>${isAdmin()?` <button class="text-link" data-note-delete="${n.id}">Supprimer</button>`:''}</article>`).join('')||'<p class="empty">Aucune note.</p>';}
function notesHTML(type,id){return `<div id="record-notes" data-record="${type}/${id}"><p>Chargement des notes…</p></div><form id="note-form" class="prototype-form"><label>Note<textarea name="body" required maxlength="10000" rows="3"></textarea></label><button class="button small" type="submit">Ajouter la note</button></form>`;}

function bindNotes(type,id,refresh){bindForm('note-form',async d=>{await api('/notes',{method:'POST',body:{...d,[type==='companies'?'company_id':'contact_id']:id}});await load();refresh();toast('Note enregistrée.');});document.querySelectorAll('[data-note-edit]').forEach(b=>b.onclick=()=>{const n=store.notes.find(n=>n.id===b.dataset.noteEdit);modal('Modifier la note',`<form id="edit-note" class="prototype-form"><label>Votre note<textarea name="body" required maxlength="10000" rows="6">${esc(n.body)}</textarea></label><button class="button" type="submit">Enregistrer</button></form>`);bindForm('edit-note',async d=>{await api('/notes/'+n.id,{method:'PATCH',body:d});dialog.close();await load();refresh();});});document.querySelectorAll('[data-note-delete]').forEach(b=>b.onclick=()=>{modal('Supprimer cette note ?',`<p>Cette suppression est définitive.</p><button class="button" id="confirm-note-delete">Confirmer la suppression</button>`);document.querySelector('#confirm-note-delete').onclick=safeAction(async()=>{await api('/notes/'+b.dataset.noteDelete,{method:'DELETE'});dialog.close();await load();refresh();});});}
function historySection(type,id){return `<section class="record-history-section"><div class="record-section-heading"><h2>Historique</h2></div><div id="record-history" data-history-key="${type}/${id}" aria-live="polite"><p class="empty">Chargement de l’historique…</p></div></section>`;}
async function loadRecordHistory(type,id,offset=0){const host=document.querySelector('#record-history');if(!host||host.dataset.historyKey!==type+'/'+id)return;try{const data=await api('/'+type+'/'+id+'/history?limit=25&offset='+offset);if(!host.isConnected||host.dataset.historyKey!==type+'/'+id)return;host.innerHTML=data.items.map(a=>`<article class="record-timeline-item"><span class="avatar mini">${esc(initials(a.actor_name))}</span><div><strong>${esc(a.summary)}</strong><p>${esc(a.actor_name)} · <time datetime="${esc(a.created_at)}">${esc(localDate(a.created_at))}</time></p></div></article>`).join('')||'<p class="empty">Aucune activité.</p>';if(data.total>25){host.insertAdjacentHTML('beforeend',`<nav class="history-pagination" aria-label="Pagination de l’historique"><button id="history-newer" ${offset===0?'disabled':''}>Plus récentes</button><span>${offset+1}–${Math.min(offset+25,data.total)} sur ${data.total}</span><button id="history-older" ${offset+25>=data.total?'disabled':''}>Plus anciennes</button></nav>`);host.querySelector('#history-newer').onclick=()=>loadRecordHistory(type,id,Math.max(0,offset-25));host.querySelector('#history-older').onclick=()=>loadRecordHistory(type,id,offset+25);}}catch(e){if(!host.isConnected)return;host.innerHTML=errorText(e.message)+'<button class="text-link" id="retry-history">Réessayer</button>';host.querySelector('#retry-history').onclick=()=>loadRecordHistory(type,id,offset);}}
function renderContactDrawer(id){const c=contactBy(id);if(!c)return;const image=store.images.find(i=>i.contact_id===id),company=companyBy(c.company_id),next=followupsFor(c,'contacts'),status=tracking(c,'contacts');modal(c.name,`<div class="contact-record-meta"><span class="tracking-badge tracking-${status.key}">${status.label}</span>${c.job_title?`<span>${esc(c.job_title)}</span>`:''}</div>${company?`<a class="contact-company-link" href="/app/entreprises/${company.id}">${icon('building')} ${esc(company.name)} ${icon('arrow')}</a>`:'<p class="record-subtle">Contact sans entreprise</p>'}<div class="record-owner-line">${icon('people')} Responsable : <strong>${esc(memberName(c.owner_user_id))}</strong></div><section class="record-coordinates"><h3>Coordonnées</h3>${addressFor(id).map(e=>`<p>${icon('mail')} <a href="mailto:${esc(e)}">${esc(e)}</a></p>`).join('')||'<p>Aucune adresse e-mail</p>'}${c.phone?`<p>${icon('phone')} <a href="tel:${esc(c.phone.replace(/\s/g,''))}">${esc(c.phone)}</a></p>`:''}</section>${recordActions(c,'contacts')}<section class="record-next-section"><div class="record-section-heading"><h2>Prochaine relance</h2><button class="text-link" id="contact-followup">＋ Planifier</button></div>${next.length?next.slice(0,3).map(r=>`<button class="record-next-action" data-followup-actions="${r.id}"><span>${icon('clock')}</span><span><strong>${esc(r.subject)}</strong><small>${esc(localDate(r.due_at))} · ${esc(memberName(r.owner_user_id))}</small></span>${icon('arrow')}</button>`).join(''):'<p class="record-subtle">Aucune relance.</p>'}</section><section class="record-notes-section"><h3 class="detail-subheading">Notes</h3>${notesHTML('contacts',id)}</section>${historySection('contacts',id)}<details class="record-card-details"><summary>Carte de visite</summary>${image?`<div class="business-card-preview"><img src="/api/v1/images/${image.id}" alt="Carte de visite du contact"></div>`:'<p class="record-subtle">Aucune carte jointe.</p>'}<label class="card-photo-button">${icon('phone')} Joindre une carte<input id="contact-card-upload" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></label></details>`,true);bindEntityActions(c,'contacts');bindNotes('contacts',id,()=>contactDrawer(id));loadNotes('contacts',id);bindRecords();document.querySelector('#contact-followup').onclick=()=>followupForm(null,id);document.querySelector('#contact-card-upload').onchange=safeAction(async()=>{const file=document.querySelector('#contact-card-upload').files[0];if(!file)return;await uploadCard(id,file);await load();contactDrawer(id);toast('Carte de visite enregistrée.');});loadRecordHistory('contacts',id);}
function renderCompanyPage(id){const c=companyBy(id);if(!c){shell('<div class="panel empty"><h1>Entreprise introuvable</h1><a class="text-link" href="/app/contacts?vue=entreprises">Revenir au répertoire</a></div>');return;}document.title=c.name+' — Ciblix';const people=store.contacts.filter(p=>p.company_id===id),next=followupsFor(c,'companies'),status=tracking(c,'companies');shell(`<a class="text-link company-back" href="/app/contacts?vue=entreprises">← Toutes les entreprises</a><div class="record-company-header"><span class="company-avatar">${esc(initials(c.name))}</span><div><span class="eyebrow">${esc(c.sector||'SECTEUR NON RENSEIGNÉ')}${c.city?' · '+esc(c.city):''}</span><h1>${esc(c.name)}</h1><p>${esc(memberName(c.owner_user_id))}</p></div><span class="tracking-badge tracking-${status.key}">${status.label}</span>${recordActions(c,'companies')}</div><div class="company-detail-grid directory-detail-grid"><section><section class="panel record-main-panel"><div class="record-section-heading"><h2>Notes</h2></div>${notesHTML('companies',id)}</section><div class="panel record-main-panel">${historySection('companies',id)}</div></section><aside><section class="panel company-context"><div class="record-section-heading"><h2>Prochaine relance</h2></div>${next.slice(0,3).map(r=>`<button class="record-next-action" data-followup-actions="${r.id}"><span>${icon('clock')}</span><span><strong>${esc(r.subject)}</strong><small>${esc(localDate(r.due_at))} · ${esc(memberName(r.owner_user_id))}</small></span>${icon('arrow')}</button>`).join('')||'<p>Aucune relance.</p>'}<button class="button small" id="company-followup">＋ Planifier une relance</button></section><section class="panel company-context"><div class="record-section-heading"><h2>Contacts <span class="number-tag">${recordContactTotal}</span></h2></div><div id="record-contacts">${people.map(p=>`<div class="company-person-coordinates"><button class="linked-person" data-open-contact="${p.id}"><span class="avatar">${esc(initials(p.name))}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.job_title||'Contact')}${p.archived_at?' · Archivé':''}</small></span>${icon('arrow')}</button>${addressFor(p.id).map(e=>`<a href="mailto:${esc(e)}">${icon('mail')} ${esc(e)}</a>`).join('')}${p.phone?`<a href="tel:${esc(p.phone.replace(/\s/g,''))}">${icon('phone')} ${esc(p.phone)}</a>`:''}</div>`).join('')||'<p>Aucun contact lié.</p>'}</div><button class="text-link" id="company-add-contact">Ajouter un contact ${icon('arrow')}</button></section><section class="panel company-context"><h2>Informations</h2><p>${esc(c.description||'Aucune description.')}</p><p>${esc(c.sector||'Secteur non renseigné')}${c.city?' · '+esc(c.city):''}</p></section></aside></div>`);bindRecords();bindEntityActions(c,'companies');bindNotes('companies',id,()=>companyPage(id));loadNotes('companies',id);document.querySelector('#company-followup').onclick=()=>followupForm(null,people.find(p=>!p.archived_at)?.id,id);document.querySelector('#company-add-contact').onclick=()=>entityForm('contacts',null,null,id);loadRecordHistory('companies',id);loadCompanyContacts(id);}

function followupForm(id=null,contactId=null,companyId=null){const r=id?store.followups.find(r=>r.id===id):{};const selected=r.contact_id||contactId;const localInput=v=>{if(!v)return new Intl.DateTimeFormat('sv-SE',{timeZone:'Africa/Tunis',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date()).replace(' ','T');return new Intl.DateTimeFormat('sv-SE',{timeZone:'Africa/Tunis',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v)).replace(' ','T');};modal(id?'Modifier la relance':'Planifier une relance',`<form id="followup-form" class="prototype-form">${id?'':`<label>Contact<select name="contact_id"><option value="">Sans contact</option>${store.contacts.filter(c=>!c.archived_at).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)} · ${esc(companyBy(c.company_id)?.name||'Sans entreprise')}</option>`).join('')}</select></label><label>Entreprise (si aucun contact)<select name="company_id"><option value="">Sans entreprise</option>${store.companies.filter(c=>!c.archived_at).map(c=>`<option value="${c.id}" ${c.id===companyId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`}<label>Objet<input name="subject" maxlength="300" value="${esc(r.subject)}" required></label><label>Échéance · heure de Tunis<input type="datetime-local" name="local_due" value="${localInput(r.due_at)}" required></label><label>Responsable<select name="owner_user_id">${ownerOptions(r.owner_user_id||session.user.id)}</select></label><button class="button" type="submit">Enregistrer la relance</button></form>`);if(!id){bindLookup(document.querySelector('#followup-form select[name=contact_id]'),'contacts',selected);bindLookup(document.querySelector('#followup-form select[name=company_id]'),'companies',companyId);}bindForm('followup-form',async d=>{d.due_at=new Date(d.local_due+':00+01:00').toISOString();delete d.local_due;if(!id){if(d.contact_id){delete d.company_id;}else d.contact_id=null;if(!d.contact_id)d.company_id=d.company_id||null;}await api('/followups'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:d});dialog.close();await sync();toast('Relance enregistrée.');});}
function followupActions(id){const r=store.followups.find(r=>r.id===id);modal('Relance',`<p>${esc(r.subject)}</p><p>${esc(localDate(r.due_at))} · ${esc(memberName(r.owner_user_id))}</p><div class="board-dialog-actions"><button class="button" id="finish-followup">${icon('check')} Terminer</button><button class="button board-secondary" id="edit-followup">${icon('clock')} Reporter / modifier</button><button class="text-link" id="cancel-followup">Annuler la relance</button>${isAdmin()?'<button class="text-link" id="delete-followup">Supprimer</button>':''}</div>`);document.querySelector('#finish-followup').onclick=safeAction(async()=>{await api('/followups/'+id,{method:'PATCH',body:{status:'completed'}});dialog.close();await sync();toast('Relance terminée.');});document.querySelector('#edit-followup').onclick=()=>followupForm(id);document.querySelector('#cancel-followup').onclick=()=>{modal('Annuler la relance',`<form class="prototype-form" id="cancel-followup-form"><label>Raison (facultative)<input name="cancellation_reason" maxlength="300"></label><button class="button" type="submit">Confirmer l’annulation</button></form>`);bindForm('cancel-followup-form',async d=>{await api('/followups/'+id,{method:'PATCH',body:{...d,status:'cancelled'}});dialog.close();await sync();});};document.querySelector('#delete-followup')?.addEventListener('click',()=>{modal('Supprimer cette relance ?',`<p>Cette suppression est définitive.</p><button class="button" id="confirm-followup-delete">Confirmer la suppression</button>`);document.querySelector('#confirm-followup-delete').onclick=safeAction(async()=>{await api('/followups/'+id,{method:'DELETE'});dialog.close();await sync();});});}
function draftForm(id){const r=store.followups.find(f=>f.id===id),person=contactBy(r.contact_id);modal('Préparer votre relance',`<p>${esc(person?.name||companyBy(r.company_id)?.name||r.subject)}</p><span class="tag">Brouillon local</span><form class="prototype-form" id="draft-form"><label>Votre message<textarea name="local_draft" required maxlength="10000" rows="8">${esc(r.local_draft||`Bonjour${person?' '+person.name.split(' ')[0]:''},\n\nJe me permets de revenir vers vous concernant notre précédent échange. Seriez-vous disponible pour faire le point ?\n\nBien cordialement,\n${session.user.name}`)}</textarea></label><button class="button" type="submit">Enregistrer le brouillon local</button><p>Enregistré dans Ciblix. Aucun envoi.</p></form>`);bindForm('draft-form',async d=>{await api('/followups/'+id,{method:'PATCH',body:d});dialog.close();await sync();toast('Brouillon enregistré.');});}
function bindRecords(){document.querySelectorAll('[data-complete-followup]').forEach(b=>b.onclick=safeAction(()=>completeFollowup(b.dataset.completeFollowup)));document.querySelectorAll('[data-edit-followup]').forEach(b=>b.onclick=()=>followupForm(b.dataset.editFollowup));document.querySelectorAll('[data-open-company]').forEach(b=>b.onclick=()=>go('/app/entreprises/'+b.dataset.openCompany));document.querySelectorAll('[data-open-contact]').forEach(b=>b.onclick=()=>{if(b.dataset.openContact)contactDrawer(b.dataset.openContact);});document.querySelectorAll('[data-followup-actions]').forEach(b=>b.onclick=()=>followupActions(b.dataset.followupActions));document.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>draftForm(b.dataset.draft));}
async function agendaLive(){const period=new URLSearchParams(location.search).get('periode')||'';const seq=++viewSequence,generation=workspaceGeneration;try{const data=await api('/followups?'+new URLSearchParams({limit:25,offset:(agendaPage-1)*25,status:reminderScope==='Terminées'?'completed':reminderScope==='Annulées'?'cancelled':'pending',...(!['Terminées','Annulées'].includes(reminderScope)&&period?{scope:period}:{}),...(reminderScope==='Mon suivi'?{owner:session.user.id}:{})}));if(seq!==viewSequence||generation!==workspaceGeneration)return;mergePage('followups',data);if(agendaPage>1&&!data.items.length){agendaPage--;return agendaLive();}document.title='Relances — Ciblix';const states=['Tous','Mon suivi','Terminées','Annulées'];const list=data.items;let groups=reminderScope==='Terminées'||reminderScope==='Annulées'?[[reminderScope,list]]:[['En retard',list.filter(r=>dayKey(r.due_at)<today())],['Aujourd’hui',list.filter(r=>dayKey(r.due_at)===today())],['À venir',list.filter(r=>dayKey(r.due_at)>today())]];groups=groups.filter(([,items])=>items.length);if(!groups.length)groups=[['Relances',[]]];shell(greeting('Relances','Une prochaine action claire pour chaque relation.','Planifier une relance')+`<div class="collection-toolbar"><div class="tabs" role="group" aria-label="Filtrer les relances">${states.map(s=>`<button data-reminder-scope="${s}" class="${s===reminderScope?'active':''}">${s}</button>`).join('')}</div><label>Période<select id="agenda-period" ${['Terminées','Annulées'].includes(reminderScope)?'disabled':''}>${[['','Toutes les échéances'],['late','En retard'],['today','Aujourd’hui'],['upcoming','À venir']].map(([value,label])=>`<option value="${value}" ${period===value?'selected':''}>${label}</option>`).join('')}</select></label><span class="tag">Échéances en heure de Tunis</span></div><div class="agenda-layout"><div>${groups.map(([name,items])=>`<section class="panel agenda-day"><div class="panel-heading"><h2>${name}</h2><span class="number-tag">${items.length}</span></div>${items.length?items.map(reminderRow).join(''):'<p class="empty">Aucune relance.</p>'}</section>`).join('')}</div></div>`);document.querySelector('#page-add').onclick=()=>followupForm();document.querySelector('#agenda-period').onchange=e=>{history.replaceState({},'','/app/relances'+(e.target.value?'?periode='+e.target.value:''));agendaPage=1;agendaLive();};document.querySelectorAll('[data-reminder-scope]').forEach(b=>b.onclick=()=>{reminderScope=b.dataset.reminderScope;agendaPage=1;agendaLive();});bindRecords();document.querySelector('.agenda-layout>div').insertAdjacentHTML('beforeend',pageControls('agenda',data,25));bindPageControls('agenda',data,25,offset=>{agendaPage=offset/25+1;agendaLive();});}catch(e){toast(e.message);}}
