  const memberTable=`<section class="panel settings-form-card"><div class="settings-section-title">${icon('people')}<div><h3>Collaborateurs de l’organisation</h3><p>Gérez les collaborateurs et leurs rôles dans votre organisation.</p></div></div><div class="settings-members-toolbar"><p>${session.members.filter(m=>m.active).length} collaborateur(s) actif(s)</p>${isAdmin()?'<button class="button" id="settings-invite">＋ Ajouter un collaborateur</button>':''}</div><div class="settings-table-scroll"><table class="settings-members-table"><thead><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>Statut</th>${isAdmin()?'<th>Actions</th>':''}</tr></thead><tbody>${session.members.map(m=>`<tr><td><span class="settings-member-name"><span class="avatar mini">${esc(initials(m.name))}</span>${esc(m.name)}${m.id===session.user.id?' (vous)':''}</span></td><td>${esc(m.email)}</td><td>${m.role==='admin'?'Administrateur':'Collaborateur'}</td><td><span class="tag">${m.active?'Actif':'Désactivé'}</span></td>${isAdmin()?`<td><button class="text-link" data-settings-member="${m.id}">Gérer</button></td>`:''}</tr>`).join('')}</tbody></table></div></section>`;
