  const users=userTabs+(roleTab?roles:`<div class="settings-users-stack">${profileBlock}${memberTable}</div>`);
  const account=`<section class="panel settings-form-card"><div class="settings-section-title">${icon('people')}<div><h3>Informations personnelles</h3><p>Les informations associées à votre connexion.</p></div></div><div class="settings-account-fields"><label>Nom<input value="${esc(session.user.name)}" readonly></label><label>E-mail<input value="${esc(session.user.email)}" readonly></label></div></section>`;
