    document.querySelectorAll('[data-toggle-password]').forEach(button=>button.onclick=()=>{const input=document.querySelector(`#settings-password input[name="${button.dataset.togglePassword}"]`),show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',(show?'Masquer':'Afficher')+' le mot de passe');});
