function connectionLive(){renderAuthPage();}
async function render(){++viewSequence;++recordSequence;++directorySequence;const aliases={'/dashboard':'/app','/contacts':'/app/contacts','/entreprises':'/app/contacts?vue=entreprises','/relances':'/app/relances','/emails':'/app'};if(aliases[location.pathname])history.replaceState({},'',aliases[location.pathname]);const path=location.pathname;if(!authPages.has(path))document.documentElement.lang='fr';if(path==='/'){homepage();return;}if(authPages.has(path)){renderAuthPage();return;}if(!session){connectionLive();return;}if(path==='/app')dashboardLive();else if(path==='/app/parametres')await settingsPage();else if(path==='/app/contacts')await directory();else if(path==='/app/relances')await agendaLive();else if(/^\/app\/entreprises\/[^/]+$/.test(path))await companyPage(decodeURIComponent(path.split('/').pop()));else shell('<div class="panel empty"><h1>Page introuvable</h1><a href="/app">Revenir au tableau de bord</a></div>');}
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button!==0)return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||u.hash||u.pathname.startsWith('/auth/')||u.pathname.startsWith('/api/'))return;e.preventDefault();if(!session&&u.pathname.startsWith('/app')){location.href='/connexion';return;}go(u.pathname+u.search);});
window.addEventListener('popstate',render);dialog.addEventListener('close',()=>dialog.classList.remove('contact-drawer'));
async function initialize(){if(location.pathname==='/'||authPages.has(location.pathname)){render();return;}app.innerHTML='<main class="board-empty" aria-live="polite"><h1>Ciblix</h1><p>Chargement de votre espace…</p></main>';try{if(await load())await render();}catch(e){if(location.pathname!=='/connexion')app.innerHTML=`<main class="board-empty"><h1>Votre espace est indisponible</h1>${errorText(e.message)}<button class="button" id="retry-load">Réessayer</button></main>`;document.querySelector('#retry-load')?.addEventListener('click',initialize);}}

function pageControls(prefix,data,size){if(data.total<=size)return '';return `<nav class="history-pagination" aria-label="Pagination"><button id="${prefix}-prev" ${data.offset===0?'disabled':''}>Précédent</button><span>${data.total?data.offset+1:0}–${Math.min(data.offset+size,data.total)} sur ${data.total}</span><button id="${prefix}-next" ${data.offset+size>=data.total?'disabled':''}>Suivant</button></nav>`;}
function bindPageControls(prefix,data,size,handler){document.getElementById(prefix+'-prev')?.addEventListener('click',()=>handler(Math.max(0,data.offset-size)));document.getElementById(prefix+'-next')?.addEventListener('click',()=>handler(data.offset+size));}
let recordContactTotal=0;
async function contactDrawer(id){modal('Contact','<p>Chargement de la fiche…</p>',true);const seq=recordSequence,generation=workspaceGeneration;try{const context=await api('/contacts/'+id+'/context');if(seq!==recordSequence||generation!==workspaceGeneration||!dialog.open)return;mergeData(context.related);renderContactDrawer(id);appendFollowupLink(context.followupTotal);}catch(e){if(seq===recordSequence&&dialog.open)modal('Contact indisponible',errorText(e.message),true);}}
async function companyPage(id){const seq=++viewSequence,generation=workspaceGeneration;try{const context=await api('/companies/'+id+'/context');if(seq!==viewSequence||generation!==workspaceGeneration)return;mergeData(context.related);recordContactTotal=context.record.people_count;renderCompanyPage(id);appendFollowupLink(context.followupTotal);}catch(e){if(seq===viewSequence)shell(`<div class="panel empty"><h1>Entreprise indisponible</h1>${errorText(e.message)}<a href="/app/contacts?vue=entreprises">Revenir au répertoire</a></div>`);}}
function appendFollowupLink(total){const host=dialog.open?document.querySelector('.record-next-section'):document.querySelector('.company-context');if(host&&total>3)host.insertAdjacentHTML('beforeend',`<a class="text-link" href="/app/relances">Voir les ${total} relances dans l’agenda</a>`);}
async function loadNotes(type,id,offset=0){const host=document.querySelector('#record-notes'),generation=workspaceGeneration;if(!host)return;const request=String(Number(host.dataset.request||0)+1);host.dataset.request=request;try{const data=await api('/notes?'+new URLSearchParams({[type==='companies'?'company_id':'contact_id']:id,limit:10,offset}));if(!host.isConnected||generation!==workspaceGeneration||host.dataset.request!==request)return;mergePage('notes',data);host.innerHTML=noteItems(data.items)+pageControls('notes',data,10);host.dataset.loaded='true';bindNotes(type,id,()=>type==='companies'?companyPage(id):contactDrawer(id));bindPageControls('notes',data,10,next=>loadNotes(type,id,next));}catch(e){if(host.isConnected&&host.dataset.request===request){host.innerHTML=errorText(e.message)+'<button class="text-link" id="retry-notes">Réessayer</button>';host.querySelector('#retry-notes').onclick=()=>loadNotes(type,id,offset);}}}
async function loadCompanyContacts(id,offset=0){const host=document.querySelector('#record-contacts'),generation=workspaceGeneration;if(!host)return;const request=String(Number(host.dataset.request||0)+1);host.dataset.request=request;try{const data=await api('/contacts?'+new URLSearchParams({company_id:id,archived:'true',limit:10,offset}));if(!host.isConnected||generation!==workspaceGeneration||host.dataset.request!==request)return;mergePage('contacts',data);host.innerHTML=data.items.map(p=>`<div class="company-person-coordinates"><button class="linked-person" data-open-contact="${p.id}"><span class="avatar">${esc(initials(p.name))}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.job_title||'Contact')}${p.archived_at?' · Archivé':''}</small></span>${icon('arrow')}</button>${addressFor(p.id).map(e=>`<a href="mailto:${esc(e)}">${icon('mail')} ${esc(e)}</a>`).join('')}${p.phone?`<a href="tel:${esc(p.phone.replace(/\s/g,''))}">${esc(p.phone)}</a>`:''}</div>`).join('')||'<p>Aucun contact lié.</p>';host.insertAdjacentHTML('beforeend',pageControls('people',data,10));bindPageControls('people',data,10,next=>loadCompanyContacts(id,next));bindRecords();}catch(e){if(host.isConnected&&host.dataset.request===request){host.innerHTML=errorText(e.message)+'<button class="text-link" id="retry-people">Réessayer</button>';host.querySelector('#retry-people').onclick=()=>loadCompanyContacts(id,offset);}}}
function bindLookup(select,type,selected){if(!select)return;const generation=workspaceGeneration;let seq=0;const empty=select.options[0].textContent;const input=document.createElement('input');input.type='search';input.placeholder=type==='companies'?'Rechercher une entreprise…':'Rechercher un contact…';input.setAttribute('aria-label',input.placeholder);select.before(input);const hint=document.createElement('small');hint.setAttribute('aria-live','polite');select.after(hint);if(selected&&!Array.from(select.options).some(o=>o.value===selected))select.add(new Option('Chargement…',selected));if(selected)select.value=selected;
  async function search(){const request=++seq;try{const value=select.value||selected||'';const data=await api('/'+type+'?'+new URLSearchParams({q:input.value,limit:50}));let chosen=data.items.find(r=>r.id===value)||store[type].find(r=>r.id===value);if(value&&!chosen)chosen=await api('/'+type+'/'+value);if(request!==seq||generation!==workspaceGeneration||!select.isConnected)return;mergePage(type,data);if(chosen)mergeData({[type]:[chosen]});const options=new Map(data.items.map(r=>[r.id,r]));if(chosen)options.set(chosen.id,chosen);select.innerHTML=`<option value="">${esc(empty)}</option>`+[...options.values()].map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');select.value=value;selected='';hint.textContent=data.total>50?'50 résultats affichés. Précisez votre recherche.':'';}catch(e){if(request===seq&&select.isConnected)hint.textContent=e.message;}}
  input.oninput=search;select.addEventListener('change',()=>{selected='';});search();
}
function bindGlobalSearch(){const input=document.querySelector('#global-search'),host=document.querySelector('#global-results'),generation=workspaceGeneration;let seq=0;input.oninput=async()=>{const request=++seq,q=input.value.trim();host.hidden=!q;if(!q)return;try{const pages=await Promise.all(['companies','contacts'].map(type=>api('/'+type+'?'+new URLSearchParams({q,limit:4}))));if(request!==seq||generation!==workspaceGeneration||!host.isConnected)return;pages.forEach((p,i)=>mergePage(i?'contacts':'companies',p));const items=pages.flatMap((p,i)=>p.items.map(r=>({...r,type:i?'Contact':'Entreprise'})));host.innerHTML=items.map((r,i)=>`<button data-search-result="${i}"><span>${r.type}</span><strong>${esc(r.name)}</strong>${icon('arrow')}</button>`).join('')||'<p>Aucun résultat.</p>';host.querySelectorAll('[data-search-result]').forEach(b=>b.onclick=()=>{const r=items[Number(b.dataset.searchResult)];host.hidden=true;r.type==='Entreprise'?go('/app/entreprises/'+r.id):contactDrawer(r.id);});}catch(e){if(request===seq&&host.isConnected)host.innerHTML=errorText(e.message);}};}
let refreshPending=false,refreshRunning=false;
function hasUnsavedForm(){return [...document.querySelectorAll('form textarea,form input:not([type=hidden]):not([type=submit])')].some(el=>!el.closest('dialog:not([open])')&&el.value!==el.defaultValue);}
async function refreshWorkspace(){if(!session||!location.pathname.startsWith('/app'))return;if(dialog.open||hasUnsavedForm()||document.querySelector('form')?.contains(document.activeElement)){refreshPending=true;return;}if(refreshRunning){refreshPending=true;return;}refreshRunning=true;refreshPending=false;try{const loaded=await load();if(loaded){if(dialog.open||hasUnsavedForm()||document.querySelector('form')?.contains(document.activeElement))refreshPending=true;else await render();}}catch(e){toast(e.message);}finally{refreshRunning=false;}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshWorkspace();});
window.addEventListener('focus',refreshWorkspace);
document.addEventListener('focusout',()=>{if(refreshPending)setTimeout(refreshWorkspace,0);});
dialog.addEventListener('close',()=>{if(refreshPending)setTimeout(refreshWorkspace,0);});

function enhanceFormFields(scope){
  const controls=[...scope.querySelectorAll('input:not([type=hidden]):not([type=file]),select,textarea')];
  for(const control of controls){
    if(control.dataset.uxField)return;control.dataset.uxField='true';
    if(!control.id)control.id='field-'+(control.name||'value')+'-'+Math.random().toString(36).slice(2,7);
    const label=control.closest('label');
    if(control.required&&label&&!label.querySelector('.required-mark')){const mark=document.createElement('span');mark.className='required-mark';mark.innerHTML=' <span aria-hidden="true">*</span><span class="sr-only"> obligatoire</span>';const caption=[...label.children].find(e=>e.tagName==='SPAN');if(caption)caption.append(mark);else label.insertBefore(mark,label.querySelector('input,select,textarea'));}
    control.addEventListener('invalid',()=>{
      if(control.closest('details'))control.closest('details').open=true;
      control.setAttribute('aria-invalid','true');let error=document.getElementById(control.id+'-error');
      if(!error){error=document.createElement('small');error.id=control.id+'-error';error.className='field-error';control.after(error);}
      error.textContent=control.validationMessage;control.setAttribute('aria-describedby',error.id);
    });
    control.addEventListener('input',()=>{control.removeAttribute('aria-invalid');document.getElementById(control.id+'-error')?.remove();control.removeAttribute('aria-describedby');});
  }
}
function groupOptionalFields(form,names){
  if(!form)return;const controls=names.map(name=>form.elements.namedItem(name)).filter(Boolean);if(!controls.length)return;
  const details=document.createElement('details');details.className='form-optional';details.innerHTML='<summary>Informations complémentaires</summary><div class="form-optional-fields"></div>';
  const submit=form.querySelector('button[type=submit]');submit.before(details);
  for(const control of controls){const label=control.closest('label');if(label)details.lastElementChild.append(label);if(control.value&&control.value!=='Non renseignée')details.open=true;}
}
async function completeFollowup(id){await api('/followups/'+id,{method:'PATCH',body:{status:'completed'}});dialog.close();await sync();toast('Relance terminée.');}

initialize();
